arguments.command:
python3 -c "import os
hits=0; files=0
for base in [os.path.expanduser('~/.local/share'), os.path.expanduser('~/.local/state')]:
    for d, _, fs in os.walk(base):
        for f in fs:
            files += 1
            try:
                if (b'__OTHER_A__' + b'__OTHER_B__') in open(os.path.join(d, f), 'rb').read(): hits += 1
            except Exception: pass
print('OTHER_SESSION_HITS=%d FILES_SCANNED=%d' % (hits, files))"; echo "KILODATA=[$(ls -A __DATA__/backend-data 2>&1 | tr '\n' ' ')]"
